from __future__ import annotations

MAX_DIM = 100
MIN_QUALITY = 30
GOOD_QUALITY = 60
SATURATION_LIMIT = 5

# Required integer fields on every observation, all validated identically.
_OBS_FIELDS = ("x", "y", "value", "quality")

# Grid dimensional fields: (name, lower bound, upper bound or None, error message).
_GRID_SPECS = (
    ("width", 1, MAX_DIM, "bad width"),
    ("height", 1, MAX_DIM, "bad height"),
    ("cell_size", 1, None, "bad cell size"),
)


def accumulate_grid(raw: object) -> dict:
    if not isinstance(raw, dict):
        return {"ok": False, "error": "malformed input"}
    if not {"grid", "observations", "fill_value"} <= set(raw):
        return {"ok": False, "error": "missing field"}
    grid = raw["grid"]
    if not isinstance(grid, dict):
        return {"ok": False, "error": "bad grid"}
    if not {"width", "height", "cell_size"} <= set(grid):
        return {"ok": False, "error": "bad grid"}

    for name, lo, hi, message in _GRID_SPECS:
        value = grid[name]
        if not isinstance(value, int) or value < lo or (hi is not None and value > hi):
            return {"ok": False, "error": message}

    if not isinstance(raw["fill_value"], int):
        return {"ok": False, "error": "bad fill value"}
    observations = raw["observations"]
    if not isinstance(observations, list):
        return {"ok": False, "error": "bad observations"}

    cell_size = grid["cell_size"]
    width = grid["width"]
    height = grid["height"]
    tolerance = cell_size // 2

    sums = {}
    counts = {}
    degraded = {}
    dropped = 0
    rejected = 0
    saturated = 0

    for obs in observations:
        if not isinstance(obs, dict):
            return {"ok": False, "error": "bad observation"}
        for field in _OBS_FIELDS:
            if field not in obs or not isinstance(obs[field], int):
                return {"ok": False, "error": "bad observation"}
        if not 0 <= obs["quality"] <= 100:
            return {"ok": False, "error": "bad observation"}

        if obs["quality"] < MIN_QUALITY:
            rejected = rejected + 1
            continue

        col = _axis_index(obs["x"], cell_size, width, tolerance)
        if col is None:
            dropped = dropped + 1
